// Node: "Normalize & Detect Intent"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Accepts both entry points (n8n Chat Trigger and the POST /webhook/coach API)
// and flags pure greetings with a regex, so "Hi" never touches the database
// or the LLM. "Hi, how do I handle X?" is NOT a pure greeting and is answered.
// -----------------------------------------------------------------------------
const GREETING = /^(?:hi|hello|hey|hiya|howdy|greetings|yo|good\s+(?:morning|afternoon|evening|day))(?:[\s,]+(?:there|all|team|coach|sara|dr\.?\s*sara(?:\s+hegy)?))?[\s!.,?]*$/i;

const raw = $json.chatInput ?? $json.body?.question ?? $json.body?.chatInput ?? $json.query?.question ?? $json.question ?? '';
const question = String(raw).replace(/\s+/g, ' ').trim();

return {
  json: {
    question,
    is_greeting: question === '' || GREETING.test(question),
    channel: $json.chatInput !== undefined ? 'chat' : 'webhook',
  },
};

// Node: "Static Greeting"   (Code · Run Once for Each Item)
// No database lookup, no LLM call.
return {
  json: {
    output: "Hello! I'm the GenX coaching assistant, grounded in Dr. Sara Hegy's documented frameworks. Ask me a leadership question, for example: \"How should I approach an underperforming VP?\"",
    route: 'greeting',
    llm_called: false,
    matched_chunks: 0,
    sources: [],
  },
};

// Node: "Build Gated SQL"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Builds the raw pgvector query. Each stream has its OWN hard similarity floor:
//   framework     1 - (embedding <=> q) >= 0.70   LIMIT 2
//   voice_sample  1 - (embedding <=> q) >= 0.65   LIMIT 2
// A chunk is stored with several index vectors (its passage + the leader
// questions it answers), so each stream keeps only the best-scoring vector per
// chunk_key before applying LIMIT 2. Only numbers (the query vector) are
// interpolated, so the user's text can never reach the SQL string.
// -----------------------------------------------------------------------------
const EMBEDDING_DIM = 1024;
const FRAMEWORK_MIN_SIMILARITY = 0.70;
const VOICE_MIN_SIMILARITY = 0.65;
const PER_STREAM_LIMIT = 2;

if ($json.error) throw new Error(`Query embedding failed: ${JSON.stringify($json.error)}`);
const embedding = $json.embeddings?.[0] ?? $json.embedding;
if (!Array.isArray(embedding) || embedding.length !== EMBEDDING_DIM || !embedding.every(Number.isFinite)) {
  throw new Error(`Expected a ${EMBEDDING_DIM}-dim query embedding from bge-m3`);
}

const q = `'[${embedding.join(',')}]'::vector(${EMBEDDING_DIM})`;

const gatedStream = (stream, minSimilarity) => `
  SELECT * FROM (
    SELECT DISTINCT ON (kv.metadata->>'chunk_key')
           kv.id, kv.session_id, kv.stream_type, kv.content, kv.metadata,
           1 - (kv.embedding <=> query.v) AS similarity
    FROM knowledge_vault kv, query
    WHERE kv.stream_type = '${stream}'
      AND 1 - (kv.embedding <=> query.v) >= ${minSimilarity}
    ORDER BY kv.metadata->>'chunk_key', kv.embedding <=> query.v
  ) best_per_chunk
  ORDER BY similarity DESC
  LIMIT ${PER_STREAM_LIMIT}`;

const sql = `
WITH query AS (SELECT ${q} AS v),
frameworks AS (${gatedStream('framework', FRAMEWORK_MIN_SIMILARITY)}
),
voice_samples AS (${gatedStream('voice_sample', VOICE_MIN_SIMILARITY)}
)
SELECT * FROM frameworks
UNION ALL
SELECT * FROM voice_samples
ORDER BY stream_type, similarity DESC;
`;

return { json: { question: $('Normalize & Detect Intent').item.json.question, sql } };

// Node: "Collect Matches"   (Code · Run Once for All Items)
// -----------------------------------------------------------------------------
// "Gated Vector Search" has "Always Output Data" on, so a zero-row result still
// arrives here as one empty item. Real rows are the ones that carry an id.
// -----------------------------------------------------------------------------
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id !== undefined && row.id !== null && typeof row.content === 'string');

const toMatch = (row) => ({
  id: Number(row.id),
  session_id: row.session_id,
  stream_type: row.stream_type,
  similarity: Math.round(Number(row.similarity) * 10000) / 10000,
  content: row.content,
  framework_name: row.metadata?.framework_name ?? null,
  matched_on: row.metadata?.index_kind === 'question' ? row.metadata.index_text : 'passage',
});

const frameworks = rows.filter((r) => r.stream_type === 'framework').map(toMatch);
const voice_samples = rows.filter((r) => r.stream_type === 'voice_sample').map(toMatch);

return [{
  json: {
    question: $('Normalize & Detect Intent').first().json.question,
    match_count: frameworks.length + voice_samples.length,
    frameworks,
    voice_samples,
  },
}];

// Node: "Circuit Breaker Fallback"   (Code · Run Once for Each Item)
// Zero chunks cleared the similarity gate: answer with the fixed fallback.
// The LLM node sits on the other branch and is never executed on this path.
return {
  json: {
    output: 'No documented coaching frameworks match this topic.',
    route: 'circuit_breaker',
    llm_called: false,
    matched_chunks: 0,
    sources: [],
  },
};

// Node: "Build Persona Request"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Persona synthesis with POSITIVE few-shot prompting: the system prompt says
// what good looks like, and two worked examples (user CONTEXT+QUESTION ->
// assistant answer) show the exact tone and structure to copy. No ban lists.
// Retrieved frameworks supply the substance; voice samples supply the rhythm.
// -----------------------------------------------------------------------------
const { question, frameworks, voice_samples } = $json;

const SYSTEM = [
  'You are Dr. Sara Hegy, executive coach at GenX Leadership Academy, answering a senior leader.',
  'How you answer:',
  '- Open with a short, direct reframe that treats the problem as a system or structure issue.',
  '- Name the framework from the CONTEXT and walk the leader through it in clear, numbered steps.',
  '- Speak in the rhythm of the VOICE SAMPLES: short declarative sentences, second person, phrases such as "Look," and "The reality is", and images of architecture, containers, signal and load.',
  '- Build every idea from the CONTEXT block. When the CONTEXT covers only part of the question, answer that part well and keep it brief.',
  '- Close with one concrete action for this week.',
  '- Stay under 220 words.',
].join('\n');

// ---- Positive few-shot examples (tone + structure to imitate) ----
const EXAMPLE_1_USER = `CONTEXT
[FRAMEWORK | SES-101]
Framework: Completion with Integrity. Define binary exit criteria before a strategic initiative starts, then enforce pre-agreed handoff constraints instead of status check-ins.

[VOICE SAMPLE | SES-101]
"Look, Mark, micromanagement is almost never an ego problem. It is an information architecture breakdown."

QUESTION
I keep re-checking my managers' work before it goes to clients. How do I stop?`;

const EXAMPLE_1_ASSISTANT = `Look, the re-checking is not a character flaw. It is an information architecture breakdown. Your system is bleeding signal, so you step in to plug the leak.

The framework is Completion with Integrity:
1. Before the next client deliverable starts, sit with its owner and write the binary exit criteria. Done means these conditions are true. Nothing vague.
2. Agree the handoff constraints up front: what is reviewed, by whom, and when.
3. Stop asking "How is this going?" Let the criteria carry the quality control.

When clarity goes up, surveillance drops.

This week: pick one deliverable, write its exit criteria with the owner, and step out of the daily review.`;

const EXAMPLE_2_USER = `CONTEXT
[FRAMEWORK | SES-101]
Framework: Completion with Integrity. Top performers fail against ambiguous standards, not capability; clear exit criteria remove the need for surveillance.

[VOICE SAMPLE | SES-101]
"Exactly. Protect your cognitive bandwidth. Let the architecture do the quality control, not your adrenaline."

QUESTION
I'm exhausted from being the final quality gate on everything.`;

const EXAMPLE_2_ASSISTANT = `The reality is, you are running quality control on adrenaline. That load is not sustainable, and it is not your job.

Your people are not failing on capability. They are failing against ambiguous standards. So we fix the standard, not the people:
1. List the three deliverables you check most often.
2. For each one, define binary exit criteria with the owner before work begins.
3. Hand off against those criteria and stay out of the middle.

Protect your cognitive bandwidth. Let the architecture do the quality control.

This week: hand one of those three deliverables back to its owner with written exit criteria, and do not review it until it is done.`;

// ---- Real context from the gated retrieval ----
const fmt = (m, label) => `[${label} | ${m.session_id} | similarity ${m.similarity.toFixed(2)}]\n${label === 'VOICE SAMPLE' ? `"${m.content}"` : m.content}`;
const context = [
  ...frameworks.map((m) => fmt(m, 'FRAMEWORK')),
  ...voice_samples.map((m) => fmt(m, 'VOICE SAMPLE')),
].join('\n\n');

return {
  json: {
    ...$json,
    persona_request: {
      model: $env.GROQ_MODEL || 'openai/gpt-oss-120b',
      temperature: 0,
      seed: 42,
      reasoning_effort: 'low',
      include_reasoning: false,
      max_tokens: 2000,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: EXAMPLE_1_USER },
        { role: 'assistant', content: EXAMPLE_1_ASSISTANT },
        { role: 'user', content: EXAMPLE_2_USER },
        { role: 'assistant', content: EXAMPLE_2_ASSISTANT },
        { role: 'user', content: `CONTEXT\n${context}\n\nQUESTION\n${question}` },
      ],
    },
  },
};

// Node: "Format Answer"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Returns the persona answer plus the exact chunks it was grounded on.
// "output" is the field the n8n Chat Trigger displays.
// -----------------------------------------------------------------------------
const ctx = $('Build Persona Request').item.json;
const answer = $json?.choices?.[0]?.message?.content;

const sources = [...ctx.frameworks, ...ctx.voice_samples].map((m) => ({
  session_id: m.session_id,
  stream_type: m.stream_type,
  similarity: m.similarity,
  ...(m.framework_name ? { framework_name: m.framework_name } : {}),
  ...(m.matched_on ? { matched_on: m.matched_on } : {}),
}));

if (typeof answer !== 'string' || answer.trim() === '') {
  const reason = $json?.error ? JSON.stringify($json.error) : 'empty LLM response';
  return {
    json: {
      output: 'The coaching assistant could not generate an answer right now. Please try again in a moment.',
      route: 'llm_error',
      llm_called: true,
      error: reason,
      matched_chunks: ctx.match_count,
      sources,
    },
  };
}

return {
  json: {
    output: answer.trim(),
    route: 'persona_answer',
    llm_called: true,
    matched_chunks: ctx.match_count,
    sources,
  },
};
